<?php
namespace App\Http\Controllers\Api\V1;
use App\Application\Users\DTOs\AddressData;use App\Application\Users\Services\AddressService;use App\Http\Controllers\Controller;use App\Http\Requests\AddressRequest;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;
class AddressController extends Controller{public function __construct(private readonly AddressService $service){}public function index(Request $r):JsonResponse{return response()->json(['status'=>'success','data'=>$this->service->list($r->user()->id)]);}public function store(AddressRequest $r):JsonResponse{return response()->json(['status'=>'success','data'=>$this->service->create($r->user()->id,(new AddressData($r->validated()))->attributes)],201);}public function update(AddressRequest $r,string $address):JsonResponse{return response()->json(['status'=>'success','data'=>$this->service->update($r->user()->id,$address,(new AddressData($r->validated()))->attributes)]);}public function destroy(Request $r,string $address):JsonResponse{$this->service->delete($r->user()->id,$address);return response()->json(['status'=>'success']);}}
